async function run() {
  let n = 0;
  for (const d of DATA) {
    n += (await prisma.recipe.updateMany({ where: { title: d.title, titleAr: null }, data: { titleAr: d.titleAr, aboutAr: d.aboutAr, ingredientsAr: JSON.stringify(d.ingredientsAr), stepsAr: JSON.stringify(d.stepsAr) } })).count;
  }
  console.log('recipes applied:', n);
  await prisma.$disconnect();
}
run().catch((e) => { console.error(e); process.exit(1); });
